INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Port-Nummern immer an bestimmte Protokolle gebunden?', 2, '[{"text": "Nein", "correct": true, "because": "Ports können individuell genutzt werden"}, {"text": "Ja", "correct": false, "because": "Standardports nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Port-Nummern in Netzwerken?', 3, '[{"text": "Dienste identifizieren", "correct": true, "because": "Leiten Daten an richtigen Dienst"}, {"text": "Daten komprimieren", "correct": false, "because": "Keine Port-Funktion"}, {"text": "Manuelle Verbindung", "correct": false, "because": "Automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Port-Bereiche gibt es?', 5, '[{"text": "Well-known Ports", "correct": true, "because": "0-1023 für Standarddienste"}, {"text": "Dynamic Ports", "correct": true, "because": "49152-65535 für temporäre Nutzung"}, {"text": "Graphic Ports", "correct": false, "because": "Kein Port-Bereich"}, {"text": "Static Ports", "correct": false, "because": "Kein Standardbegriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Port 80 ist für HTTP reserviert. b) Alle Ports sind öffentlich zugänglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Firewall ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Konfiguration von Port-Nummern?', 4, '[{"text": "Firewall-Einstellungen", "correct": false, "because": "Können Ports blockieren"}, {"text": "Standardports", "correct": false, "because": "Wichtig für Dienste"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Ports"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Port 443 für HTTPS genutzt wird?', 2, '[{"text": "Ja", "correct": true, "because": "Standardport für HTTPS"}, {"text": "Nein", "correct": false, "because": "443 ist HTTPS"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Port ist typischerweise für E-Mail-Versand reserviert?', 3, '[{"text": "Port 25", "correct": true, "because": "SMTP nutzt Port 25"}, {"text": "Port 80", "correct": false, "because": "Für HTTP"}, {"text": "Port 110", "correct": false, "because": "Für POP3"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle nutzen bekannte Port-Nummern?', 5, '[{"text": "FTP", "correct": true, "because": "Ports 20/21"}, {"text": "SSH", "correct": true, "because": "Port 22"}, {"text": "Bluetooth", "correct": false, "because": "Kein Netzwerkprotokoll"}, {"text": "USB", "correct": false, "because": "Keine Port-Nummern"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Port-Nummern ermöglichen Multiplexing. b) Sie sind immer statisch. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) dynamische Ports existieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Nutzung von Port-Nummern?', 4, '[{"text": "Netzwerkprotokoll", "correct": false, "because": "Definiert Port-Nutzung"}, {"text": "Dienstzuordnung", "correct": false, "because": "Leitet Daten"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Port für mehrere Dienste genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Aber Konflikte möglich"}, {"text": "Nein", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei Port-Nummern auftreten?', 4, '[{"text": "Port-Konflikte", "correct": true, "because": "Mehrere Dienste auf einem Port"}, {"text": "Firewall-Blockade", "correct": true, "because": "Verhindert Kommunikation"}, {"text": "Hohe Auflösung", "correct": false, "because": "Kein Port-Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Port-Nummern immer offen sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Firewalls schützen Ports"}, {"text": "Ja", "correct": false, "because": "Zugang kontrolliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Konfiguration von Port-Nummern?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Schützt vor Angriffen"}, {"text": "Maximale Öffnung", "correct": false, "because": "Erhöht Risiko"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "Standards effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Port 22 ist für SSH. b) Ports sind nur für TCP relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch UDP nutzt Ports"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten standardisierte Port-Nummern?', 5, '[{"text": "Interoperabilität", "correct": true, "because": "Einheitliche Zuordnung"}, {"text": "Einfache Konfiguration", "correct": true, "because": "Bekannte Ports genutzt"}, {"text": "Datenkompression", "correct": false, "because": "Kein Port-Vorteil"}, {"text": "Grafische Darstellung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Port-Nummern unwichtig?', 3, '[{"text": "Protokollzuordnung", "correct": false, "because": "Bestimmt Dienst"}, {"text": "Firewall-Regeln", "correct": false, "because": "Schützen Netzwerk"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Port 53 für DNS genutzt wird?', 2, '[{"text": "Ja", "correct": true, "because": "Standardport für DNS"}, {"text": "Nein", "correct": false, "because": "53 ist DNS"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind alle Port-Nummern frei wählbar?', 3, '[{"text": "Nein", "correct": true, "because": "Well-known Ports reserviert"}, {"text": "Ja", "correct": false, "because": "Standards existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Nutzung von Port-Nummern?', 4, '[{"text": "Webserver-Konfiguration", "correct": true, "because": "Nutzt Port 80/443"}, {"text": "Bildbearbeitung", "correct": false, "because": "Keine Netzwerkaufgabe"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Port-Fokus"}]');
